%[text] # LCC Matching
%[text] ## Basic Functions & Variables
%[text] ### Initialize Variables
%[text] Plot Colors
clear
pltc = ["#0072BD", "#4DBEEE", "#77AC30", "#EDB120", "#D95319", "#A2142F", "#7E2F8E"];
%[text] Settings
% If using an RF choke
flagRFC = false;
%[text] Constants
u0 = 4*pi*10^-7; % permeability of free space
%[text] Frequency for each nuclei of interest
f1H  = 120.34E6; % Hz
f31P = 49E6; % Hz

w1H = 2*pi*f1H; % rad/s
w31P = 2*pi*f31P; % rad/s
%[text] RF choke
if flagRFC
    Lrf = 6.8E-6; % H
    Rrf = Lrf/50; % resistance based on Q of 50 (datasheet)
end
%[text] Q factor for capacitor
Qc = 4000;
%[text] ### Define Functions
%[text] Impedance of a capacitor
syms Z_C(w,C)
Z_C(w,C) = 1/(w*C*Qc) - 1i/(w*C) % Ohms %[output:2b9df6b8]
%[text] Impedance of an inductor
syms Z_L(w,L,R)
Z_L(w,L,R) = R + 1i*w*L % Ohms %[output:238370d9]
%[text] Impedance of a match capacitor & RF choke
syms Z_crfc(w,C)
if flagRFC %[output:group:380eb22a]
    Z_crfc(w,C) = 1/(1/Z_L(w,Lrf,Rrf) + 1/Z_C(w,C)) % Ohms
else
    Z_crfc(w,C) = Z_C(w,C) % Ohms %[output:2f675a1d]
end %[output:group:380eb22a]
%[text] Impedance of an LCC trap
syms Ztr_LCC(w,C_s,C_p,L_tr,R_L)
Ztr_LCC(w,C_s,C_p,L_tr,R_L) = 1/(1/Z_C(w,C_p) + 1/(Z_L(w,L_tr,R_L) + Z_C(w,C_s))) % Ohms %[output:2a90748c]
%[text] Impedance of an LLC trap parallel to RF choke
syms Ztr_LCCrf(w,C_s,C_p,L_tr,R_L)
if flagRFC %[output:group:50c4c85d]
    Ztr_LCCrf(w,C_s,C_p,L_tr,R_L) = 1/(1/Z_L(w,Lrf,Rrf) + 1/Z_C(w,C_p) + 1/(Z_L(w,L_tr,R_L) + Z_C(w,C_s))) % Ohms
else
    Ztr_LCCrf(w,C_s,C_p,L_tr,R_L) = 1/(1/Z_C(w,C_p) + 1/(Z_L(w,L_tr,R_L) + Z_C(w,C_s))) %[output:6021555b]
end %[output:group:50c4c85d]
clear w C L L_tr C_s C_p R_L R
%[text] Total Impedance
syms Z_tot(Z_coil,w,L_rf,R_rf,C_p,L_tr,R_tr,C_s)
Z_tot(Z_coil,w,L_rf,R_rf,C_p,L_tr,R_tr,C_s) = Z_coil + 1/(1/Z_L(w,L_rf,R_rf) + 1/Z_C(w,C_p) + 1/(Z_L(w,L_tr,R_tr) + Z_C(w,C_s))) %[output:5ddcdc1c]
combine(simplifyFraction(Z_tot(Z_coil,w,L_rf,R_rf,C_p,L_tr,R_tr,C_s))) %[output:66017038]
clear Z_coil w L_rf R_rf C_p L_tr R_tr C_s
%[text] ### Inputs
%[text] Settings
% If starting with a match trap
flagMT = true;

% If using hand wound inductor
flagHW = false;
%[text] Number of traps
N = 1;
%[text] Reactances of coil @ corresponding frequencies
% With RF choke & diodes
Z1H  = 9.16 - 0.48195i; % Ohms, measured on VNA
Z31P = 3.614 + 30.234i; % Ohms, measured on VNA
if flagMT %[output:group:7046cfd2]
%[text] Current trap values
    Cs_init = 15E-12;
    Cp_init = 15E-12;
    Ltr_init = 150E-9;
    QLtr_init = 65;

    % Calculate coil impedance at both frequencies
    Zc1H  =  Z1H - N*double(Ztr_LCCrf(w1H,Cs_init,Cp_init,Ltr_init,(w1H*Ltr_init)/QLtr_init)) %[output:00299274]
    Zc31P = Z31P - N*double(Ztr_LCCrf(w31P,Cs_init,Cp_init,Ltr_init,(w31P*Ltr_init)/QLtr_init)) %[output:2ce0d77c]
    % C_init = 12E-12;
    % Zc1H = Z1H - double(Z_crfc(w1H,C_init))
    % Zc31P = Z31P - double(Z_crfc(w31P,C_init))
%[text] Theoretical capacitor required to match coil
    C1H = 1/(w1H*Zc1H)*(1/Qc - 1i) %[output:1afde573]
    C31P = 1/(w31P*Zc31P)*(1/Qc - 1i) %[output:6cefc3cb]
else
%[text] Capacitor required to match coil
    C1H = 6.2E-12; %#ok<*UNRCH>
    C31P = 43E-12;
end %[output:group:7046cfd2]
% Reactance of match circuit
Z1Hm = double(Z_crfc(w1H,C1H)) %[output:120bd745]
Z31Pm = double(Z_crfc(w31P,C31P)) %[output:95d879b6]
%[text] ### Outputs
%[text] #### Solenoid Calculations
%[text] Determine parameters to design the inductor, based on given limitations
% Trap minimum and maximum inductance
Lmin = 4/((C31P - C1H)*(w1H^2 - w31P^2)) % H %[output:1387085f]
Lmax = 500/w1H % H %[output:4657f64c]

if flagHW
    r = 2E-3; % radius, m (largest we would want to go based off size of trap circuit
    l = 5E-3; % length, m (longest we would want to go based off size of trap circuit)
    d_awg = 24; % diameter, awg
    d_m = (0.127*92^((36-d_awg)/39))/1000;
    Nmax = floor(l/d_m); % number of turns, based on diameter of wire & length of inductor

    clear d_awg

%[text] Calculate the theoretical inductance of the solenoid
    Lth = (u0*pi*(r^2)*(Nmax^2))/l;
    Ltr = Lth;

    fprintf('d = %.0f mm', r*2000);
    fprintf('l = %.0f mm', l*1000);
    fprintf('N = %i', Nmax);
    fprintf('L = %.2f nH', Ltr*1E9);
%[text] Calculate resistance of inductor
    p = 1.68E-8; % resistivity of copper

    idx = 5.88146792793386E-06; % skin depth @ 1H
    s1 = idx*(1 - exp(-(d_m/2)/idx));
    z = (0.62006*(d_m/2)/idx);
    y = 0.189774/(1 + 0.272481*(z^1.82938 - z^-0.99457)^2)^1.0941;
    Aeff = pi*(2*(d_m/2)*s1 - s1^2)*(1 + y); % effective cross sectional area
    R1H = (p*pi*2*r*Nmax)/Aeff; % resistance of inductor @ 1H

    idx = 9.2247219941196E-06; % skin depth @ 31P
    s1 = idx*(1 - exp(-(d_m/2)/idx));
    z = (0.62006*(d_m/2)/idx);
    y = 0.189774/(1 + 0.272481*(z^1.82938 - z^-0.99457)^2)^1.0941;
    Aeff = pi*(2*(d_m/2)*s1 - s1^2)*(1 + y); % effective cross sectional area
    R31P = (p*pi*2*r*Nmax)/Aeff; % resistance of inductor @ 31P

    RLtr = (R1H+R31P)/2;
    clear p idx s1 z y Aeff d_awg
else
%[text] Select reasonable inductance value
    Ltr = 100E-9;
    QLtr = 65;
    R1H = (w1H*Ltr)/100;
    R31P = (w31P*Ltr)/100;
end
%[text] Trap capacitance calculations
Cp_th(1) = (C31P + C1H)/2 + sqrt((C31P - C1H)^2/4 - (C31P - C1H)/(Ltr*(w1H^2 - w31P^2))); % F
Cp_th(2) = (C31P + C1H)/2 - sqrt((C31P - C1H)^2/4 - (C31P - C1H)/(Ltr*(w1H^2 - w31P^2))) % F %[output:257071dd]
Cs_th = (C1H - Cp_th)./(w1H^2*Ltr*(C1H - Cp_th) + 1) % F %[output:361d9c38]
%[text] Resonance of each trap
ftr = 1E-6./(2.*pi.*sqrt(Ltr.*(Cs_th.*Cp_th)./(Cs_th + Cp_th))) % Hz %[output:7595ade6]
%[text] Select whichever solution is farther from 1H
if abs(ftr(1) - f1H) > abs(ftr(2) - f1H)
    sol = 1;
else
    sol = 2;
end
%%
%[text] ## Impedance Matching
close all
Cs = (1:10:61).*1E-12;
Cp = (2:0.01:200).*1E-12;

Z = Z1H + double(Ztr_LCCrf(w1H,Cs(1),Cp,Ltr,R1H));
figure; %[output:038bb6f1]
plot(log(Cp./1E-12), real(Z),'LineStyle','-','Color',pltc(1),'DisplayName',['Z_{tr} (C_s=' num2str(Cs(1)/1E-12) 'pF)']); %[output:038bb6f1]
hold on %[output:038bb6f1]
plot(log(Cp./1E-12), imag(Z),'LineStyle',':','Color',pltc(1),'HandleVisibility','off') %[output:038bb6f1]
for i = 2:length(Cs)
    Z = Z1H + double(Ztr_LCCrf(w1H,Cs(i),Cp,Ltr,R1H));
    plot(log(Cp./1E-12), real(Z),'LineStyle','-','Color',pltc(i),'DisplayName',['Z_{tr} (C_s=' num2str(Cs(i)/1E-12) 'pF)']); %[output:038bb6f1]
    plot(log(Cp./1E-12), imag(Z),'LineStyle',':','Color',pltc(i),'HandleVisibility','off')
end
legend('Location', 'northeast') %[output:038bb6f1]
xlabel('log(pF)');ylabel('Ohms'); title('Impedance vs Capcitance (^{1}H)') %[output:038bb6f1]
ylim([-100 100]) %[output:038bb6f1]
xlim([log(min(Cp./1E-12)) log(max(Cp./1E-12))]) %[output:038bb6f1]
xticks([log(max(Cp./100E-12)) log(max(Cp./40E-12)) log(max(Cp./20E-12)) log(max(Cp./10E-12)) log(max(Cp./4E-12)) log(max(Cp./2E-12)) log(max(Cp./1E-12))]) %[output:038bb6f1]
xticklabels({'2', '10', '20', '50', '100', '200'}) %[output:038bb6f1]

Cs = (1:10:61).*1E-12;
Cp = (5:0.1:500).*1E-12;

Z = Z31P + double(Ztr_LCCrf(w31P,Cs(1),Cp,Ltr,R31P));
figure; %[output:02d83093]
plot(log(Cp./1E-12), real(Z),'LineStyle','-','Color',pltc(1),'DisplayName',['Z_{tr} (C_s=' num2str(Cs(1)/1E-12) 'pF)']); %[output:02d83093]
hold on %[output:02d83093]
plot(log(Cp./1E-12), imag(Z),'LineStyle',':','Color',pltc(1),'HandleVisibility','off') %[output:02d83093]
for i = 2:length(Cs)
    Z = Z31P + double(Ztr_LCCrf(w31P,Cs(i),Cp,Ltr,R31P));
    plot(log(Cp./1E-12), real(Z),'LineStyle','-','Color',pltc(i),'DisplayName',['Z_{tr} (C_s=' num2str(Cs(i)/1E-12) 'pF)']); %[output:02d83093]
    plot(log(Cp./1E-12), imag(Z),'LineStyle',':','Color',pltc(i),'HandleVisibility','off')
end
legend('Location', 'northwest') %[output:02d83093]
xlabel('log(pF)');ylabel('Ohms'); title('Impedance vs Capcitance (^{31}P)') %[output:02d83093]
ylim([-100 100]) %[output:02d83093]
xlim([log(min(Cp./1E-12)) log(max(Cp./1E-12))]) %[output:02d83093]
xticks([log(max(Cp./100E-12)) log(max(Cp./50E-12)) log(max(Cp./25E-12)) log(max(Cp./10E-12)) log(max(Cp./5E-12)) log(max(Cp./2.5E-12)) log(max(Cp./1E-12))]) %[output:02d83093]
xticklabels({'5', '10', '20', '50', '100', '200', '500'}) %[output:02d83093]
%%
%[text] ## Experimental Data
%[text] ### Constraints
Cmin = (10^12/((w1H^2)*Ltr))*2 %[output:2c01c250]
Cmax = (10^12/((w31P^2)*Ltr))*2 %[output:34a6f159]
%[text] ### Testing
%[text] Test range
w = (29:1:153).*(2*pi*1E6);
y = [-300 100];
Cs = 11E-12;
Cp = 17E-12;
RLtr = (w.*Ltr)./QLtr;
%[text] #### Reactance Matching (varying C1)
idx = 3;
Cidx = Cs/1E-12;
Cidx = (Cidx-(3*idx):idx:Cidx+(3*idx)).*1E-12;

close all
figure; %[output:72c42f6e]
Ztr = double(Ztr_LCCrf(w,Cidx(1),Cp,Ltr,RLtr)); 
plot(w./(2*pi*1E6), real(Ztr),'LineStyle','-','Color',pltc(1),'DisplayName',['Z_{tr} (C_s=' num2str(Cidx(1)/1E-12) 'pF)']); xlabel('MHz');ylabel('Ohms');xlim([min(w)/(2*pi*1E6) max(w)/(2*pi*1E6)]); ylim([y(1), y(2)]); %[output:72c42f6e]
hold on %[output:72c42f6e]
plot(w./(2*pi*1E6), imag(Ztr),'LineStyle',':','Color',pltc(1),'HandleVisibility','off') %[output:72c42f6e]
plot(w1H./(2*pi*1E6), real(Z1Hm),'.black','HandleVisibility','off');  %[output:72c42f6e]
plot(w1H./(2*pi*1E6), imag(Z1Hm),'oblack','HandleVisibility','off');  %[output:72c42f6e]
plot(w31P./(2*pi*1E6), real(Z31Pm),'.black','HandleVisibility','off'); %[output:72c42f6e]
plot(w31P./(2*pi*1E6), imag(Z31Pm),'oblack','HandleVisibility','off'); %[output:72c42f6e]
for i = 2:length(Cidx)
    Ztr = double(Ztr_LCCrf(w,Cidx(i),Cp,Ltr,RLtr));
    plot(w./(2*pi*1E6), real(Ztr),'LineStyle','-','Color',pltc(i),'DisplayName',['Z_{tr} (C_s=' num2str(Cidx(i)/1E-12) 'pF)']); %[output:72c42f6e]
    plot(w./(2*pi*1E6), imag(Ztr),'LineStyle',':','Color',pltc(i),'HandleVisibility','off');
end
xline(w1H/(2*pi*1E6),'--','HandleVisibility','off') %[output:72c42f6e]
xline(w31P/(2*pi*1E6),'--','HandleVisibility','off') %[output:72c42f6e]
legend('Location', 'southwest') %[output:72c42f6e]
title('Impedance vs. Frequency (varying C_s)'); %[output:72c42f6e]
hold off %[output:72c42f6e]
%[text] #### Reactance Matching (varying C2)
idx = 3;
Cidx = Cp/1E-12;
Cidx = (Cidx-(3*idx):idx:Cidx+(3*idx)).*1E-12;

figure; %[output:41390f07]
Ztr = double(Ztr_LCCrf(w,Cs,Cidx(1),Ltr,RLtr)); 
plot(w./(2*pi*1E6), real(Ztr),'LineStyle','-','Color',pltc(1),'DisplayName',['Z_{tr} (C_p=' num2str(Cidx(1)/1E-12) 'pF)']); xlabel('MHz');ylabel('Ohms');xlim([min(w)/(2*pi*1E6) max(w)/(2*pi*1E6)]); ylim([y(1), y(2)]); %[output:41390f07]
hold on %[output:41390f07]
plot(w./(2*pi*1E6), imag(Ztr),'LineStyle',':','Color',pltc(1),'HandleVisibility','off') %[output:41390f07]
plot(w1H./(2*pi*1E6), real(Z1Hm),'.black','HandleVisibility','off');  %[output:41390f07]
plot(w1H./(2*pi*1E6), imag(Z1Hm),'oblack','HandleVisibility','off');  %[output:41390f07]
plot(w31P./(2*pi*1E6), real(Z31Pm),'.black','HandleVisibility','off'); %[output:41390f07]
plot(w31P./(2*pi*1E6), imag(Z31Pm),'oblack','HandleVisibility','off'); %[output:41390f07]
for i = 2:length(Cidx)
    Ztr = double(Ztr_LCCrf(w,Cs,Cidx(i),Ltr,RLtr));
    plot(w./(2*pi*1E6), real(Ztr),'LineStyle','-','Color',pltc(i),'DisplayName',['Z_{tr} (C_p=' num2str(Cidx(i)/1E-12) 'pF)']); %[output:41390f07]
    plot(w./(2*pi*1E6), imag(Ztr),'LineStyle',':','Color',pltc(i),'HandleVisibility','off');
end
xline(w1H/(2*pi*1E6),'--','HandleVisibility','off') %[output:41390f07]
xline(w31P/(2*pi*1E6),'--','HandleVisibility','off') %[output:41390f07]
legend('Location', 'southwest') %[output:41390f07]
title('Impedance vs. Frequency (varying C_p)'); %[output:41390f07]
hold off %[output:41390f07]
%[text] #### Reactance Matching (varying L)
idx = 20;
Lidx = (round(Ltr*1E9)-(3*idx):idx:round(Ltr*1E9)+(3*idx)).*1E-9;

figure; %[output:1cb727bc]
Ztr = double(Ztr_LCCrf(w,Cs,Cp,Lidx(1),RLtr)); 
plot(w./(2*pi*1E6), real(Ztr),'LineStyle','-','Color',pltc(1),'DisplayName',['Z_{tr} (L=' num2str(Lidx(1)/1E-9) 'nH)']); xlabel('MHz');ylabel('Ohms');xlim([min(w)/(2*pi*1E6) max(w)/(2*pi*1E6)]); ylim([y(1), y(2)]); %[output:1cb727bc]
hold on %[output:1cb727bc]
plot(w./(2*pi*1E6), imag(Ztr),'LineStyle',':','Color',pltc(1),'HandleVisibility','off') %[output:1cb727bc]
plot(w1H./(2*pi*1E6), real(Z1Hm),'.black','HandleVisibility','off');  %[output:1cb727bc]
plot(w1H./(2*pi*1E6), imag(Z1Hm),'oblack','HandleVisibility','off');  %[output:1cb727bc]
plot(w31P./(2*pi*1E6), real(Z31Pm),'.black','HandleVisibility','off'); %[output:1cb727bc]
plot(w31P./(2*pi*1E6), imag(Z31Pm),'oblack','HandleVisibility','off'); %[output:1cb727bc]
for i = 2:length(Lidx)
    Ztr = double(Ztr_LCCrf(w,Cs,Cp,Lidx(i),RLtr));
    plot(w./(2*pi*1E6), real(Ztr),'LineStyle',':','Color',pltc(i),'DisplayName',['Z_{tr} (L=' num2str(Lidx(i)/1E-9) 'nH)']); %[output:1cb727bc]
    plot(w./(2*pi*1E6), imag(Ztr),'LineStyle',':','Color',pltc(i),'HandleVisibility','off');
end
xline(w1H/(2*pi*1E6),'--','HandleVisibility','off') %[output:1cb727bc]
xline(w31P/(2*pi*1E6),'--','HandleVisibility','off') %[output:1cb727bc]
legend('Location', 'southwest') %[output:1cb727bc]
title('Impedance vs. Frequency (varying L)'); %[output:1cb727bc]
hold off %[output:1cb727bc]
%%
%[text] Final Values
w = (39:0.01:133).*(2*pi*1E6);
% y = [-1400 100];
Ztr = double(Ztr_LCCrf(w,Cs,Cp,Ltr,RLtr));  %[output:88aac510]
figure;

plot(w./(2*pi*1E6), real(Ztr),'LineStyle','-','Color',pltc(1),'DisplayName','Z_{tr}'); xlabel('MHz');ylabel('Ohms');xlim([min(w)/(2*pi*1E6) max(w)/(2*pi*1E6)]); ylim([y(1), y(2)]);
hold on
plot(w./(2*pi*1E6), imag(Ztr),'LineStyle',':','Color',pltc(1),'HandleVisibility','off')
plot(w1H./(2*pi*1E6), real(Z1Hm),'.black','HandleVisibility','off'); 
plot(w1H./(2*pi*1E6), imag(Z1Hm),'oblack','HandleVisibility','off'); 
plot(w31P./(2*pi*1E6), real(Z31Pm),'.black','HandleVisibility','off');
plot(w31P./(2*pi*1E6), imag(Z31Pm),'oblack','HandleVisibility','off');
xline(w1H/(2*pi*1E6),'--','HandleVisibility','off')
xline(w31P/(2*pi*1E6),'--','HandleVisibility','off')
legend('Location', 'southwest')
title('Impedance vs. Frequency');
hold off

f = w./(2*pi*1E6);
[~,fLCC] = max(real(Ztr));
fprintf('\nX @ 1H: %.2f Ohms', imag(Ztr(8421)))
fprintf('\nX @ 31P: %.2f Ohms', imag(Ztr(1088)))
fprintf('LCC match f0 = %.2f MHz', f(fLCC))

